# 2026-08-06: the industry no longer chooses a palette, because there is only
# one. What an industry actually differentiates is the vocabulary, the section
# copy, the registration questions and the operational template — which is
# what the marketing page has always claimed ("Templates change the vocabulary
# and the forms, not just the colours") and what the note below this mapping
# used to promise while the code did the opposite.
#
# Colour is now one knob the studio sets from its own logo. A dance studio and
# a maths tutor differ in their words and their photographs; they never
# differed in their hue, and pretending otherwise cost five of the seven
# palettes a visible semantic role — a green theme could not show "saved".
DEFAULT_STYLE_ID = "studio"

# Shape is a presentation choice, not a palette choice, and now that the
# palette no longer varies it is the only preset dimension left in this table.
# The studio can still pick sharp or rounded buttons and a different display
# face without touching a colour.
STYLE_SHAPE = {
    "studio": {"button_style": "soft", "font_mood": "serif"},
}

HARMONY_LABELS: dict[str, dict[str, str]] = {
    "warm paper / one accent": {"zh": "暖纸 · 单一强调色",
                                "en": "Warm paper / one accent"},
}


def harmony_label(harmony: str) -> dict[str, str]:
    """Return the human-readable name of a colour relationship."""

    return dict(HARMONY_LABELS.get(harmony, {"zh": harmony, "en": harmony}))


def style_theme(style_id: str, scheme: str = "light", accent_hue: float | None = None) -> dict:
    """Return one style's flat token map for a given light/dark scheme.

    Falls back to the style's only available mode when the requested one does
    not exist, and to the default style when the id is unknown, so a stale
    tenant setting can never render an empty theme.

    With `accent_hue` the palette is SOLVED rather than read from the generated
    literal above. That is the studio's one colour knob: the hue comes from the
    studio (usually out of its logo), the lightness and saturation stay the
    product's, so a neon logo becomes a deep pine and cannot produce a button
    nobody can read. Without it the literal is used unchanged, which keeps the
    common path free of any solving and keeps the generated file the thing the
    drift tests pin.
    """

    preset = VISUAL_STYLE_PRESETS.get(style_id) or VISUAL_STYLE_PRESETS[DEFAULT_STYLE_ID]
    resolved_id = style_id if style_id in VISUAL_STYLE_PRESETS else DEFAULT_STYLE_ID
    themes = preset["themes"]
    mode = scheme if scheme in themes else preset["modes"][0]
    shape = {
        "style_id": resolved_id,
        "theme_mode": "preset",
        **STYLE_SHAPE.get(resolved_id, STYLE_SHAPE[DEFAULT_STYLE_ID]),
    }
    if accent_hue is None:
        return {**shape, **themes[mode]}
    solved = palette.build(palette.studio_theme(float(accent_hue)), mode == "dark")
    return {**shape, "accent_hue": round(float(accent_hue) % 360, 1), **solved}


def accent_starting_points() -> list[dict]:
    """The swatch shelf the owner picks from before reaching for the picker."""

    return palette.accent_shelf()


def accent_hue_of_colour(value: str) -> float:
    """The hue this product will actually use for a studio-supplied colour."""

    return palette.accent_hue_from(value)


